// These components can use Portals
// when they need to render elsewhere in the DOM.

function Parent() {
  const handleClick = () => {
    console.log("Parent clicked");
  };

  return (
    <div onClick={handleClick}>
      <Modal />
    </div>
  );
}

function Modal() {
  return createPortal(
