// Clicking the button can bubble through
// the React tree to Parent, even though
// the button is outside Parent's DOM node.

function App() {
  return (
    <div>
      {/* Normal rendering */}
      <NormalComponent />

      {/* Portal rendering */}
      <Modal />
    </div>
  );
}

function NormalComponent() {
  return <div>Inside App's DOM</div>;
}

function Modal() {
  return createPortal(
    <div>Rendered elsewhere in the DOM</div>,
    document.getElementById("modal-root")
  );
}
